CREATE OR REPLACE FUNCTION public.apply_payment_fee_ledger_refund(p_ledger_id uuid, p_refunded_gross_cents bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator_id uuid;
  v_gross bigint;
  v_creator_net bigint;
  v_previous_refunded bigint;
  v_previous_reversed bigint;
  v_platform_fee bigint;
  v_processing_fee bigint;
  v_was_credited boolean;
  v_refunded bigint;
  v_target_reversed bigint;
  v_platform_attribution bigint;
  v_processing_attribution bigint;
  v_rounding_adjustment bigint;
  v_delta bigint;
begin
  select creator_id, gross_amount_cents, creator_net_cents, refunded_amount_cents,
         earnings_reversed_cents, platform_fee_cents, processing_fee_cents,
         earnings_credited_at is not null
  into v_creator_id, v_gross, v_creator_net, v_previous_refunded,
       v_previous_reversed, v_platform_fee, v_processing_fee, v_was_credited
  from public.payment_fee_ledger where id = p_ledger_id for update;
  if not found or v_gross <= 0 then return 0; end if;
  v_refunded := least(v_gross, greatest(v_previous_refunded, p_refunded_gross_cents, 0));
  v_target_reversed := round((v_creator_net::numeric * v_refunded::numeric) / v_gross::numeric);
  v_platform_attribution := round((v_platform_fee::numeric * v_refunded::numeric) / v_gross::numeric);
  v_processing_attribution := round((v_processing_fee::numeric * v_refunded::numeric) / v_gross::numeric);
  v_rounding_adjustment := v_refunded - v_target_reversed - v_platform_attribution - v_processing_attribution;
  v_delta := greatest(0, v_target_reversed - v_previous_reversed);
  if v_delta > 0 and v_was_credited then
    update public.profiles
    set total_earnings_cents = greatest(0, coalesce(total_earnings_cents, 0) - v_delta)
    where id = v_creator_id;
  end if;
  update public.payment_fee_ledger
  set refunded_amount_cents = v_refunded,
      earnings_reversed_cents = v_target_reversed,
      platform_fee_refund_attribution_cents = v_platform_attribution,
      processing_fee_refund_attribution_cents = v_processing_attribution,
      refund_allocation_rounding_cents = v_rounding_adjustment,
      status = case when v_refunded >= v_gross then 'refunded' else status end,
      updated_at = now()
  where id = p_ledger_id;
  return case when v_was_credited then v_delta else 0 end;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_payment_dispute_state(p_dispute_id text, p_payment_intent_id text, p_charge_id text, p_disputed_amount_cents bigint, p_currency text, p_status text, p_event_created bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_recorded boolean;
begin
  if nullif(trim(p_dispute_id), '') is null
     or nullif(trim(p_payment_intent_id), '') is null
     or nullif(trim(p_charge_id), '') is null then
    raise exception 'dispute, payment intent, and charge ids are required';
  end if;
  if p_disputed_amount_cents is null or p_disputed_amount_cents < 0 then
    raise exception 'disputed amount must be nonnegative';
  end if;
  if nullif(trim(p_currency), '') is null or nullif(trim(p_status), '') is null then
    raise exception 'dispute currency and status are required';
  end if;
  if p_event_created is null or p_event_created < 0 then
    raise exception 'Stripe event-created time is invalid';
  end if;
  insert into public.payment_dispute_state (
    stripe_dispute_id, stripe_payment_intent_id, stripe_charge_id,
    disputed_amount_cents, currency, status, stripe_event_created
  ) values (
    p_dispute_id, p_payment_intent_id, p_charge_id,
    p_disputed_amount_cents, lower(p_currency), p_status, p_event_created
  )
  on conflict (stripe_dispute_id) do update
  set stripe_payment_intent_id = excluded.stripe_payment_intent_id,
      stripe_charge_id = excluded.stripe_charge_id,
      disputed_amount_cents = excluded.disputed_amount_cents,
      currency = excluded.currency,
      status = excluded.status,
      stripe_event_created = excluded.stripe_event_created,
      updated_at = now()
  where excluded.stripe_event_created >= payment_dispute_state.stripe_event_created
  returning true into v_recorded;
  return coalesce(v_recorded, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_payment_refund_state(p_payment_intent_id text, p_charge_id text, p_charge_amount_cents bigint, p_refunded_amount_cents bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_refunded bigint;
begin
  if nullif(trim(p_payment_intent_id), '') is null then raise exception 'payment intent id is required'; end if;
  if nullif(trim(p_charge_id), '') is null then raise exception 'charge id is required'; end if;
  if p_charge_amount_cents is null or p_charge_amount_cents < 0 then
    raise exception 'charge amount must be nonnegative';
  end if;
  if p_refunded_amount_cents is null or p_refunded_amount_cents < 0
     or p_refunded_amount_cents > p_charge_amount_cents then
    raise exception 'refunded amount must be between zero and the charge amount';
  end if;
  insert into public.payment_refund_state (
    stripe_payment_intent_id, stripe_charge_id, charge_amount_cents, refunded_amount_cents
  ) values (
    p_payment_intent_id, p_charge_id, p_charge_amount_cents, p_refunded_amount_cents
  )
  on conflict (stripe_payment_intent_id) do update
  set stripe_charge_id = excluded.stripe_charge_id,
      charge_amount_cents = greatest(payment_refund_state.charge_amount_cents, excluded.charge_amount_cents),
      refunded_amount_cents = least(
        greatest(payment_refund_state.charge_amount_cents, excluded.charge_amount_cents),
        greatest(payment_refund_state.refunded_amount_cents, excluded.refunded_amount_cents)
      ),
      updated_at = now()
  returning refunded_amount_cents into v_refunded;
  return v_refunded;
end;
$function$
